{"command":"cat << 'EOF' > pattern0.py
import json

def set_cell(p, r, c, n=None, i=None, v=None, e=None, ep=None):
    cell = {"name": "pattern_set_cell", "arguments": {"pattern": p, "row": r, "channel": c}}
    if n is not None: cell["arguments"]["note"] = n
    if i is not None: cell["arguments"]["instrument"] = i
    if v is not None: cell["arguments"]["volume"] = v
    if e is not None: cell["arguments"]["effect"] = e
    if ep is not None: cell["arguments"]["effect_param"] = ep
    return cell

calls = []

# Pattern 0 - Intro Bass & Kick
for r in range(0, 64):
    # Kick on channel 3 (0-indexed)
    if r % 16 == 0:
        calls.append(set_cell(0, r, 3, "C-4", 4))

    # Bass on channel 2
    if r % 8 == 0:
        calls.append(set_cell(0, r, 2, "G-2", 3))
    elif r % 8 == 4:
        calls.append(set_cell(0, r, 2, "G-3", 3))
    elif r % 8 == 6:
        calls.append(set_cell(0, r, 2, "Bb-2", 3))

# Pattern 1 - Add Snare & Hi-hat
for r in range(0, 64):
    # Kick
    if r % 16 == 0:
        calls.append(set_cell(1, r, 3, "C-4", 4))
    # Snare
    if r % 16 == 8:
        calls.append(set_cell(1, r, 4, "C-4", 5))
    # Hi-hat
    if r % 4 == 4 or r % 8 == 2 or r % 8 == 6:
         calls.append(set_cell(1, r, 5, "C-4", 6))

    # Bass
    if r % 8 == 0:
        calls.append(set_cell(1, r, 2, "G-2", 3))
    elif r % 8 == 4:
        calls.append(set_cell(1, r, 2, "G-3", 3))
    elif r % 8 == 6:
        calls.append(set_cell(1, r, 2, "Bb-2", 3))

print(json.dumps(calls))
EOF
python3 pattern0.py > pattern0.json
ft2 batch pattern0.json"}

