{"command":"cat << 'EOF' > compose.py
import json

def set_cell(p, r, c, n=None, i=None, v=None, e=None, ep=None):
    args = {"pattern": p, "row": r, "channel": c}
    if n is not None: args["note"] = n
    if i is not None: args["instrument"] = i
    if v is not None: args["volume"] = v
    if e is not None: args["effect"] = e
    if ep is not None: args["effect_param"] = ep
    return {"name": "pattern_set_cell", "arguments": args}

calls = []

def add_drums(p):
    for r in range(0, 64):
        # Kick
        if r % 16 == 0:
            calls.append(set_cell(p, r, 3, "C-4", 4))
        # Snare
        if r % 16 == 8:
            calls.append(set_cell(p, r, 4, "C-4", 5))
        # Hi-hat
        if r % 4 == 4:
            calls.append(set_cell(p, r, 5, "C-4", 6, v=32))
        if r % 8 == 2 or r % 8 == 6:
            calls.append(set_cell(p, r, 5, "C-4", 6, v=16))

def add_bass(p, variant=0):
    for r in range(0, 64):
        if r % 8 == 0:
            calls.append(set_cell(p, r, 2, "G-2", 3))
        elif r % 8 == 4:
            calls.append(set_cell(p, r, 2, "G-3", 3))
        elif r % 8 == 6:
            if variant == 1 and r > 32:
                 calls.append(set_cell(p, r, 2, "Eb-2", 3))
            else:
                 calls.append(set_cell(p, r, 2, "Bb-2", 3))

melody = [
    (0, "G-4"), (4, "G-4"), (8, "Bb-4"), (12, "D-5"),
    (16, "C-5"), (20, "Bb-4"), (24, "A-4"), (28, "F-4"),
    (32, "G-4"), (36, "G-4"), (40, "Bb-4"), (44, "D-5"),
    (48, "F-5"), (52, "D-5"), (56, "C-5"), (60, "Bb-4")
]

# Pattern 0: Intro (Bass only)
add_bass(0)

# Pattern 1: Intro + Drums
add_bass(1)
add_drums(1)

# Pattern 2: Main Theme
add_bass(2)
add_drums(2)
for r, n in melody:
    calls.append(set_cell(2, r, 0, n, 1, e=4, ep=0x44)) # Vibrato

# Pattern 3: Theme + Arp
add_bass(3, variant=1)
add_drums(3)
for r, n in melody:
    calls.append(set_cell(3, r, 0, n, 1, e=4, ep=0x44))
# Fast Arp on Ch 1
for r in range(0, 64):
    if r % 4 == 0:
        calls.append(set_cell(3, r, 1, "G-4", 2, v=30, e=0, ep=0x37)) # G-Bb-D arp (0, 3, 7 semitones)
    elif r % 4 == 2:
        calls.append(set_cell(3, r, 1, "D-4", 2, v=30, e=0, ep=0x37))

# Pattern 4: Breakdown (Filter-like effect using volume slides?)
add_bass(4)
for r in range(0, 64):
    if r % 16 == 0:
        calls.append(set_cell(4, r, 0, "G-5", 1, v=64, e=10, ep=0x01)) # Slide down volume

# Pattern 5: Build up
add_bass(5)
add_drums(5)
for r in range(0, 64):
    if r % 2 == 0:
        calls.append(set_cell(5, r, 6, "C-4", 5, v=r)) # Snare roll build up

print(json.dumps(calls))
