{"command":"cat << 'EOF' > compose_final.py
import json

def set_cell(p, r, c, n=None, i=None, v=None, e=None, ep=None):
    args = {"pattern": p, "row": r, "channel": c}
    if n is not None: args["note"] = n
    if i is not None: args["instrument"] = i
    if v is not None: args["volume"] = v
    if e is not None: args["effect"] = e
    if ep is not None: args["effect_param"] = ep
    return {"name": "pattern_set_cell", "arguments": args}

calls = []

def add_drums(p):
    for r in range(0, 64):
        # Kick
        if r % 16 == 0:
            calls.append(set_cell(p, r, 3, "C-4", 4, v=48))
        # Snare
        if r % 16 == 8:
            calls.append(set_cell(p, r, 4, "C-4", 5, v=48))
        # Hi-hat
        if r % 4 == 4:
            calls.append(set_cell(p, r, 5, "C-4", 6, v=20))
        if r % 8 == 2 or r % 8 == 6:
            calls.append(set_cell(p, r, 5, "C-4", 6, v=10))

def add_bass(p, variant=0):
    for r in range(0, 64):
        if r % 8 == 0:
            calls.append(set_cell(p, r, 2, "G-2", 3, v=40))
        elif r % 8 == 4:
            calls.append(set_cell(p, r, 2, "G-3", 3, v=35))
        elif r % 8 == 6:
            note = "Bb-2" if variant == 0 else "Eb-2"
            calls.append(set_cell(p, r, 2, note, 3, v=35))

melody1 = [
    (0, "G-4"), (4, "G-4"), (8, "Bb-4"), (12, "D-5"),
    (16, "C-5"), (20, "Bb-4"), (24, "A-4"), (28, "F-4"),
    (32, "G-4"), (36, "G-4"), (40, "Bb-4"), (44, "D-5"),
    (48, "F-5"), (52, "D-5"), (56, "C-5"), (60, "Bb-4")
]

melody2 = [
    (0, "G-4"), (4, "D-5"), (8, "C-5"), (12, "Bb-4"),
    (16, "A-4"), (20, "Bb-4"), (24, "G-4"), (28, "F-4"),
    (32, "G-4"), (36, "Bb-4"), (40, "D-5"), (44, "F-5"),
    (48, "G-5"), (52, "F-5"), (56, "D-5"), (60, "C-5")
]

# Patterns
for p in range(7):
    # Bass & Drums
    if p == 0:
        add_bass(p)
    elif p == 4:
        add_bass(p, variant=1)
    else:
        add_bass(p, variant=(1 if p in [3, 6] else 0))
        add_drums(p)

    # Melody
    if p in [2, 3]:
        for r, n in melody1:
            calls.append(set_cell(p, r, 0, n, 1, v=50, e=4, ep=0x44))
    if p in [5, 6]:
        for r, n in melody2:
            calls.append(set_cell(p, r, 0, n, 1, v=50, e=4, ep=0x44))

    # Arp
    if p in [3, 6]:
        for r in range(0, 64):
            if r % 4 == 0:
                note = "G-4" if p == 3 else "C-4"
                calls.append(set_cell(p, r, 1, note, 2, v=25, e=0, ep=0x37))
            elif r % 4 == 2:
                note = "D-4" if p == 3 else "G-3"
                calls.append(set_cell(p, r, 1, note, 2, v=25, e=0, ep=0x37))

    # Breakdown / Build up (Pattern 4)
    if p == 4:
        for r in range(0, 64, 4):
            calls.append(set_cell(p, r, 6, "C-4", 6, v=r//2))

print(json.dumps(calls))
